def transform(grid):
    blocks = [grid[r][start:start + 4] for start in (0, 5, 10, 15) for r in range(4)]
    # Reorganize into four 4x4 color-pattern blocks.
    patterns = [
        [[grid[r][start + c] for c in range(4)] for r in range(4)]
        for start in (0, 5, 10, 15)
    ]
    priority = {5: 1, 8: 2, 4: 3, 9: 4}
    out = []
    for r in range(4):
        row = []
        for c in range(4):
            colors = [pattern[r][c] for pattern in patterns if pattern[r][c] != 0]
            row.append(max(colors, key=lambda color: priority[color]) if colors else 0)
        out.append(row)
    return out
